import clsx from 'clsx';
import { forwardRef } from 'react';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { getVoucherBadgeClass } from '~/entities/voucher/lib/get-voucher-badge-class';
import { IssueVoucherStatusCd } from '~/shared/api/dtos/enums';
import { MAX_INPUT_NUMBER } from '~/shared/constants/form';
import { useVoucherNavigation } from '~/shared/lib/hooks/use-navigate';
import { parseToDate } from '~/shared/lib/web-view-bridge';

export const VoucherItem = forwardRef<HTMLElement, { item: VoucherItemDTO }>(function VoucherItem({ item }, ref) {
  const { navigateToVoucherDetail } = useVoucherNavigation();
  const isActive = item.isuVouchSttusCd === IssueVoucherStatusCd.이용자사용중;

  const handleClick = () => {
    if (!item?.vouchId) return;
    navigateToVoucherDetail(item.vouchId, item);
  };

  const formatAmount = (num?: string | number | null): string => {
    if (num === null || num === undefined || isNaN(Number(num))) return '';
    const numAmt = Number(num);
    if (numAmt > MAX_INPUT_NUMBER) return MAX_INPUT_NUMBER.toLocaleString();
    return numAmt.toLocaleString();
  };

  const badgeClass = isActive ? getVoucherBadgeClass(item.vouchTyCd) : 'badge-cancel';

  return (
    <article ref={ref} className={clsx('voucher-card', !isActive && 'is-disabled')} onClick={handleClick}>
      <div className="card-header">
        <span className={`common-badge ${badgeClass}`}>{item.vouchTyNm}</span>
        <h2 className="voucher-name">{item.vouchNm}</h2>
        <p className="voucher-period common-font-roboto">
          {parseToDate(item.rcvfverUseStartDt, 'yyyy.MM.dd') + ' ~ ' + parseToDate(item.rcvfverUseEndDt, 'yyyy.MM.dd')}
          {!isActive && item.vouchProcStepNm ? `(${item.vouchProcStepNm})` : ''}
        </p>
      </div>
      <div className="card-balance">
        {!isActive && <span className="balance-label">보유 잔액</span>}
        <span className="balance-num common-font-roboto">{formatAmount(item.pbmBalanceOf ?? 0)}</span>
        <span className="balance-unit">원</span>
      </div>
    </article>
  );
});
